/*
 * 9share_conf.h -- what 9share.conf(5) says.
 *
 * The file is read by the parser in 9share_conf.c, which was generated by hbnf from
 * grammars/9share.hbnf (see HACKING); the build does not need hbnf.  The blocks are
 * checked as they are read (conf.c), so what is in a struct nineshare_conf is valid.
 */
#ifndef NINESHARE_CONF_H
#define NINESHARE_CONF_H

#include <stddef.h>

/* export "NAME" { directory DIR  host HOST  [hold SECONDS] } */
struct nineshare_export {
    char   *name, *directory, *host;
    int     hold;                       /* seconds a broken link is waited for; 0: the default, 600 */
    size_t  line;                       /* the line of the file the block starts on */
};

/* mount "NAME" { user USER  at MOUNTPOINT  [hold SECONDS] } */
struct nineshare_mount {
    char   *name, *user, *at;
    int     hold;                       /* 0: the default, 600 */
    size_t  line;
};

struct nineshare_conf {
    struct nineshare_export *exports;
    size_t                 nexports;
    struct nineshare_mount  *mounts;
    size_t                 nmounts;
};

void nineshare_conf_init(struct nineshare_conf *c);
void nineshare_conf_free(struct nineshare_conf *c);

/* Read the file into *c (after nineshare_conf_init).  Returns 0, or -1 after having printed every
 * error as "file:line: message" on standard error; the blocks that were fine are in *c anyway.
 * A file that does not exist is an error here: ask nineshare_file_exists first when it may be absent. */
int nineshare_conf_parse(const char *path, struct nineshare_conf *c);

/* Used by the parser's actions: take the block (which becomes the conf's) after checking it.  NULL
 * when it was taken, else the message; the block is then the caller's to free. */
const char *nineshare_conf_add_export(struct nineshare_conf *c, const struct nineshare_export *e);
const char *nineshare_conf_add_mount(struct nineshare_conf *c, const struct nineshare_mount *m);

/* What may go where: a name is letters, digits and . _ - (not first: . _ -); a user is a login
 * name; a host is a name as ssh knows it (not starting with -); a path is absolute and has only
 * letters, digits and . _ + @ - / (so it can be put in an option string and a command line as it
 * is).  Each returns 1 if valid. */
int nineshare_valid_name(const char *s);
int nineshare_valid_user(const char *s);
int nineshare_valid_host(const char *s);
int nineshare_valid_path(const char *s);

#endif /* NINESHARE_CONF_H */
